effect.shader:
void main(){
    vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
    vec3 c = src.a>0.0? src.rgb/src.a : src.rgb;
    float d = min(min(acScreenNorm.x, 1.0-acScreenNorm.x), min(acScreenNorm.y, 1.0-acScreenNorm.y));
    float b = smoothstep(width, 0.0, d);
    vec3 outc = mix(c, color.rgb, b*amount);
    gl_FragColor = vec4(outc,1.0)*src.a;
}
